const items = collection.map(item => {
  const retailPrice = item.retail_price || 0;
  const currentPrice = item.lowest_ask || 0;
  const discountPercent = ((retailPrice - currentPrice) / retailPrice * 100).toFixed(1);

  // Fee calculation: 13% StockX + 13% Shopify + 4% shipping
  const totalFees = currentPrice * 0.30;
  const grossProfit = currentPrice - retailPrice;
  const netProfit = grossProfit - totalFees;

  return {
    sku: item.uuid,
    name: item.title,
    category: item.category,
    retail_price: retailPrice.toFixed(2),
    current_price: currentPrice.toFixed(2),
    discount_percent: discountPercent,
    gross_profit: grossProfit.toFixed(2),
    estimated_fees: totalFees.toFixed(2),
    net_profit: netProfit.toFixed(2),
    url: `https://stockx.com/search?s=${item.slug}`,
    volume_24h: item.volume_24h || 0,
    timestamp: new Date().toISOString()
  };
});

return {
  all_items: items,
  deals: items.filter(item => parseFloat(item.net_profit) >= 50),
  top_5_deals: items.filter(item => parseFloat(item.net_profit) >= 50).sort((a,b) => parseFloat(b.net_profit) - parseFloat(a.net_profit)).slice(0, 5),
  total_deals_found: items.filter(item => parseFloat(item.net_profit) >= 50).length,
  total_potential_profit: items.filter(item => parseFloat(item.net_profit) >= 50).reduce((sum, item) => sum + parseFloat(item.net_profit), 0).toFixed(2)
};

