const products = collection.map(product => {
  const current_price = parseFloat(product.price);
  const price_7d_ago = parseFloat(product.price_7d_ago) || current_price;
  const change_pct = ((current_price - price_7d_ago) / price_7d_ago * 100).toFixed(1);

  let alert_type = 'NONE';
  let alert_triggered = false;

  if (change_pct < -10) {
    alert_type = 'PRICE_DROP';
    alert_triggered = true;
  } else if (change_pct > 15 && product.volume_24h > 50) {
    alert_type = 'SELLING_OPPORTUNITY';
    alert_triggered = true;
  }

  return {
    id: product.id,
    name: product.name,
    set: product.set_name,
    condition: product.condition,
    price: current_price.toFixed(2),
    price_7d: price_7d_ago.toFixed(2),
    change_pct: change_pct,
    volume_24h: product.volume_24h,
    alert_type: alert_type,
    alert_triggered: alert_triggered,
    timestamp: new Date().toISOString()
  };
});

return {
  all_products: products,
  alerts_triggered: products.filter(p => p.alert_triggered),
  alert_count: products.filter(p => p.alert_triggered).length
};

